import {campusLayout} from './campus-layout.js?v=36.0.0';
const components=l=>{if(l.componentIndex)return l.componentIndex;const map=new Map();let index=0;for(const n of l.campus.nodes){if(map.has(n.id))continue;const todo=[n.id];map.set(n.id,index);while(todo.length){const id=todo.pop();for(const e of l.campus.halls)if(e.a===id||e.b===id){const next=e.a===id?e.b:e.a;if(!map.has(next)){map.set(next,index);todo.push(next);}}}index++;}l.componentIndex=map;return map;};
function region(l,p){const n=l.campus.nodes.reduce((a,b)=>Math.hypot(a.x-p.x,a.y-p.y)<Math.hypot(b.x-p.x,b.y-p.y)?a:b);return components(l).get(n.id);}
export function campusTrip(mall,stores,fromFloor,from,toFloor,target,action={},preparedLayouts=null){const layouts=preparedLayouts||Array.from({length:mall._floorCount||0},(_,f)=>campusLayout(mall,f,stores));if(!layouts.length){const first=campusLayout(mall,0,stores);for(let f=0;f<first.plan.levels.length;f++)layouts.push(f?campusLayout(mall,f,stores):first);}const points=[{floor:fromFloor,p:from},{floor:toFloor,p:target}];for(const [floor,l]of layouts.entries())for(const e of l.escalators)points.push({floor,p:e.landing,connector:e});const regions=points.map(p=>region(layouts[p.floor],p.p));const dist=Array(points.length).fill(Infinity),prev=Array(points.length).fill(-1),seen=new Set();dist[0]=0;while(seen.size<points.length){let at=-1;for(let i=0;i<points.length;i++)if(!seen.has(i)&&(at<0||dist[i]<dist[at]))at=i;if(at<0||!Number.isFinite(dist[at]))break;if(at===1)break;seen.add(at);const a=points[at];for(let j=0;j<points.length;j++){if(j===at)continue;const b=points[j];let cost=Infinity;if(a.floor===b.floor&&regions[at]===regions[j])cost=Math.hypot(a.p.x-b.p.x,a.p.y-b.p.y);else if(a.connector&&b.connector&&a.connector.id===b.connector.id&&a.floor!==b.floor&&a.connector.floors.includes(b.floor)&&b.connector.floors.includes(a.floor))cost=250*Math.abs(a.floor-b.floor);if(dist[at]+cost<dist[j]){dist[j]=dist[at]+cost;prev[j]=at;}}}if(!Number.isFinite(dist[1]))return [];const chain=[];for(let n=1;n!==-1;n=prev[n])chain.unshift(n);const steps=[];for(let i=1;i<chain.length;i++){const a=points[chain[i-1]],b=points[chain[i]];if(a.floor!==b.floor){const last=steps.at(-1),transfer={floor:b.floor,connectorId:a.connector.id,landing:b.p};if(last&&last.point===a.p)last.action={transfer};else steps.push({point:a.p,action:{transfer}});}else steps.push({point:b.p,action:i===chain.length-1?action:{}});}if(!steps.length)steps.push({point:target,action});return steps;}
